import numpy as np

def D(f, x, h=1e-5):
    """central difference: approximates f'(x) with error O(h^2)"""
    return (f(x + h) - f(x - h)) / (2 * h)

derivatives = [
    ('x^2',    lambda t: t**2,  lambda t: 2*t),      # power rule
    ('x^3',    lambda t: t**3,  lambda t: 3*t**2),   # power rule
    ('sin(x)', np.sin,          np.cos),             # fixed
    ('exp(x)', np.exp,          np.exp),             # itself
    ('ln(x)',  np.log,          lambda t: 1/t),      # fixed
]
print(f"{'function':10s} {'x':>5s} {'numerical':>10s} {'rule':>10s}")
for name, f, df in derivatives:
    for x in [0.5, 2.0]:
        print(f'{name:10s} {x:5.1f} {D(f, x):10.4f} {df(x):10.4f}')
